import AVFAudio
import Foundation
import VCSpeakers

/// Audio fixtures generated by `swift scripts/MakeFixtures.swift` into `<repo>/.fixtures`.
enum Fixtures {
    static let directory = URL(filePath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .appending(path: ".fixtures", directoryHint: .isDirectory)

    static let enrolledNames = ["Daniel", "Samantha", "Rishi", "Karen"]

    static func url(_ name: String) -> URL { directory.appending(path: name) }

    static var meetingAvailable: Bool {
        (["meeting.wav", "meeting.truth.json"] + enrolledNames.map { "enroll_\($0).wav" })
            .allSatisfy { FileManager.default.fileExists(atPath: url($0).path(percentEncoded: false)) }
    }

    /// True when fixtures exist and the FluidAudio models can be downloaded/loaded.
    static func modelsAndFixturesAvailable() async -> Bool {
        guard meetingAvailable else { return false }
        do {
            try await SpeakerModels.prepare()
            return true
        } catch {
            print("VCSpeakers fixture tests skipped: models unavailable (\(error))")
            return false
        }
    }

    /// Mono Float32 samples and their sample rate.
    static func load(_ name: String) throws -> (samples: [Float], sampleRate: Double) {
        let file = try AVAudioFile(forReading: url(name), commonFormat: .pcmFormatFloat32, interleaved: false)
        let frames = AVAudioFrameCount(file.length)
        guard let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: frames) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        try file.read(into: buffer)
        guard let data = buffer.floatChannelData?[0] else { throw CocoaError(.fileReadCorruptFile) }
        return (Array(UnsafeBufferPointer(start: data, count: Int(buffer.frameLength))), file.processingFormat.sampleRate)
    }

    struct TruthTurn: Decodable {
        let speaker: String
        let start: Double
        let end: Double
    }

    static func truth() throws -> [TruthTurn] {
        try JSONDecoder().decode([TruthTurn].self, from: Data(contentsOf: url("meeting.truth.json")))
    }
}
